/// <summary>
/// getFreezeStatus' request: is this warehouse frozen for a wall-to-wall count?
/// </summary>
[DataContractAttribute]
class HSMobileOpsFreezeStatusRequest
{
    DataAreaId dataAreaId;
    str warehouseId;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}
